import{_ as t,c as i,o,ae as n}from"./chunks/framework.CliRSA9F.js";const a="/images/positioning.webp",g=JSON.parse('{"title":"Positioning","description":"","frontmatter":{},"headers":[],"relativePath":"features/positioning.md","filePath":"features/positioning.md"}'),s={name:"features/positioning.md"};function r(d,e,l,u,c,p){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="positioning" tabindex="-1">Positioning <a class="header-anchor" href="#positioning" aria-label="Permalink to &quot;Positioning&quot;">​</a></h1><h2 id="define-your-podcast-s-strategic-identity" tabindex="-1">Define Your Podcast&#39;s Strategic Identity <a class="header-anchor" href="#define-your-podcast-s-strategic-identity" aria-label="Permalink to &quot;Define Your Podcast&#39;s Strategic Identity&quot;">​</a></h2><p>Positioning (titled <strong>Podcast Positioning</strong> in the app) helps you articulate what makes your podcast unique across six key dimensions. By clearly defining your subject matter, audience, value proposition, style, listening context, and differentiators, you create a strategic foundation that guides your content and optimization efforts.</p><p><img src="'+a+'" alt="Positioning Dashboard" width="600px" style="display:block;margin:0 auto;"></p><h2 id="why-positioning-matters" tabindex="-1">Why Positioning Matters <a class="header-anchor" href="#why-positioning-matters" aria-label="Permalink to &quot;Why Positioning Matters&quot;">​</a></h2><p>A well-defined podcast position helps you:</p><ul><li><strong>Stand out in search results</strong> by focusing on specific topics and audiences</li><li><strong>Create consistent content</strong> that resonates with your ideal listeners</li><li><strong>Optimize effectively</strong> by knowing which keywords and topics matter most</li><li><strong>Attract the right audience</strong> by clearly communicating your value</li></ul><h2 id="the-six-positioning-dimensions" tabindex="-1">The Six Positioning Dimensions <a class="header-anchor" href="#the-six-positioning-dimensions" aria-label="Permalink to &quot;The Six Positioning Dimensions&quot;">​</a></h2><p>Positioning guides you through defining your podcast across six color-coded dimensions:</p><h3 id="subject-blue" tabindex="-1">Subject (Blue) <a class="header-anchor" href="#subject-blue" aria-label="Permalink to &quot;Subject (Blue)&quot;">​</a></h3><p><strong>What topics does your podcast cover?</strong></p><p>Define the core subjects your podcast explores. Be specific enough to stand out, but broad enough to sustain content. You can select up to 4 subjects.</p><p><em>Examples: true crime investigations, startup funding, personal finance, mindfulness practices</em></p><h3 id="audience-purple" tabindex="-1">Audience (Purple) <a class="header-anchor" href="#audience-purple" aria-label="Permalink to &quot;Audience (Purple)&quot;">​</a></h3><p><strong>Who is your ideal listener?</strong></p><p>Identify the specific people your podcast serves. Understanding your audience helps you create content that resonates and choose keywords that reach the right listeners. Select up to 3 audiences.</p><p><em>Examples: first-time entrepreneurs, busy parents, college students, small business owners</em></p><h3 id="promise-green" tabindex="-1">Promise (Green) <a class="header-anchor" href="#promise-green" aria-label="Permalink to &quot;Promise (Green)&quot;">​</a></h3><p><strong>What value do listeners get?</strong></p><p>Articulate the benefit listeners receive from your podcast. This is your value proposition - what transformation or outcome you deliver. Select up to 3 promises.</p><p><em>Examples: actionable business advice, entertainment during commutes, inspiration for creative projects</em></p><h3 id="style-amber" tabindex="-1">Style (Amber) <a class="header-anchor" href="#style-amber" aria-label="Permalink to &quot;Style (Amber)&quot;">​</a></h3><p><strong>How do you deliver your content?</strong></p><p>Define your podcast&#39;s format and delivery approach. Your style affects how listeners perceive and engage with your content. Select up to 2 style elements.</p><p><em>Examples: conversational interviews, solo deep-dives, storytelling narrative, panel discussions</em></p><h3 id="listening-context-pink" tabindex="-1">Listening Context (Pink) <a class="header-anchor" href="#listening-context-pink" aria-label="Permalink to &quot;Listening Context (Pink)&quot;">​</a></h3><p><strong>When do listeners tune in?</strong></p><p>Identify the situations and moments when people listen to your podcast. Understanding listening context helps you optimize episode length and content structure. Select up to 2 contexts.</p><p><em>Examples: morning commute, workout sessions, evening wind-down, weekend learning</em></p><h3 id="differentiator-red" tabindex="-1">Differentiator (Red) <a class="header-anchor" href="#differentiator-red" aria-label="Permalink to &quot;Differentiator (Red)&quot;">​</a></h3><p><strong>What makes you unique?</strong></p><p>Articulate your competitive advantage - what sets your podcast apart from others covering similar topics. This is your lightning bolt - the reason listeners choose you. Select up to 3 differentiators.</p><p><em>Examples: insider industry access, unique methodology, celebrity interviews, data-driven insights</em></p><h2 id="how-to-use-positioning" tabindex="-1">How to Use Positioning <a class="header-anchor" href="#how-to-use-positioning" aria-label="Permalink to &quot;How to Use Positioning&quot;">​</a></h2><h3 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h3><p>When you first visit Positioning, PodSEO may suggest topics based on your existing content and any AI visibility data. You can accept these suggestions or start fresh.</p><h3 id="the-guided-wizard" tabindex="-1">The Guided Wizard <a class="header-anchor" href="#the-guided-wizard" aria-label="Permalink to &quot;The Guided Wizard&quot;">​</a></h3><p>The Guided Wizard walks you through the four core dimensions step by step — <strong>Subject</strong>, <strong>Audience</strong>, <strong>Promise</strong>, and <strong>Style</strong>:</p><ol><li><strong>Review suggestions</strong> - See recommended topics for each dimension</li><li><strong>Add your own</strong> - Enter custom topics that fit your podcast</li><li><strong>Refine selections</strong> - Remove topics that don&#39;t fit, prioritize the most important ones</li><li><strong>Complete the four core dimensions</strong> - Build the foundation of your positioning framework</li></ol><p><strong>Listening Context</strong> and <strong>Differentiator</strong> aren&#39;t part of the wizard. You add these two dimensions directly on the dashboard grid whenever you&#39;re ready, alongside the topics you defined in the wizard.</p><h3 id="refining-over-time" tabindex="-1">Refining Over Time <a class="header-anchor" href="#refining-over-time" aria-label="Permalink to &quot;Refining Over Time&quot;">​</a></h3><p>Your positioning isn&#39;t permanent. As your podcast evolves, revisit and update your positioning to reflect:</p><ul><li>New content directions you&#39;re exploring</li><li>Audience feedback and listener demographics</li><li>Competitive landscape changes</li><li>Growth strategies and goals</li></ul><h2 id="integration-with-other-features" tabindex="-1">Integration with Other Features <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;Integration with Other Features&quot;">​</a></h2><p>Your positioning choices influence recommendations throughout PodSEO:</p><ul><li><strong>Keyword Strategy</strong> - Suggested keywords align with your subject and audience</li><li><strong><a href="/features/ai-mentions.html">AI Mentions</a></strong> - Topics tracked reflect your positioning dimensions</li><li><strong><a href="/features/planner.html">Planner</a></strong> - Metadata alignment and AI suggestions consider your defined style and promise</li><li><strong><a href="/features/command-center.html">Command Center</a></strong> - Tasks and signals prioritize improvements aligned with your positioning</li></ul><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Positioning is available on paid plans. Free users see a preview of the feature; defining and editing your positioning requires a paid plan. The feature helps you build a strategic foundation that enhances all other PodSEO optimization features.</p><p><strong>Related Features</strong>: Use <a href="/features/keyword-strategy.html">Keyword Strategy</a> to build on your positioning with targeted keywords, and check <a href="/features/ai-mentions.html">AI Mentions</a> to see how AI platforms perceive your podcast&#39;s topics.</p>',49)])])}const m=t(s,[["render",r]]);export{g as __pageData,m as default};
